window.AUTH=window.AUTH||{};window.AUTH["18-525"]={"d":"18-525","id":"2018/18-525","n":"Fort Bend County, Texas v. Davis","briefs":[{"k":"petitioner","label":"Brief of petitioner Fort Bend County","date":"2019-02-25","url":"https://www.supremecourt.gov/DocketPDF/18/18-525/89564/20190225161559608_18-525%20ts.pdf","side":"pet","n":86},{"k":"respondent","label":"Brief of respondent Lois Davis","date":"2019-03-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-525/93371/20190327121753185_18525bs.pdf","side":"res","n":145},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-04-03","url":"https://www.supremecourt.gov/DocketPDF/18/18-525/95317/20190403155843349_18-525bsacUnitedStates.pdf","side":"us","n":71},{"k":"reply","label":"Reply of petitioner Fort Bend County","date":"2019-04-12","url":"https://www.supremecourt.gov/DocketPDF/18/18-525/96292/20190412135103946_18-525%20rb.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-525_m6hn.pdf","tr":true,"items":[{"t":"case","label":"Albemarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"sum":"The Court held that backpay should be awarded based on a court’s discretion. The decision in this case should be considered in light of the goals of the Equal Employment Opportunity Act. Because the prospect of a backpay award could ensure the use of equal employment practices, it serves the purposes of the Act and should be awarded in this case.","sumSrc":"Oyez","by":{"0":"34, 48, 49","2":"19, 20","3":"18"}},{"t":"case","label":"Alexander v. Gardner-Denver Co.","cite":"415 U.S. 36","y":1974,"id":"1973/72-5847","sc":1,"op":1,"sum":"An employee's statutory right to trial de novo under Title VII of the Civil Rights Act of 1964 is not foreclosed by prior submission of his claim to final arbitration under the nondiscrimination clause of a collective-bargaining.agreement.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 4, 48","1":"4, 26, 44","2":"21","3":"19"}},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"op":7,"ar":14,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"49, 50","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Atascadero State Hosp. v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"sum":"Respondent's action is proscribed by the Eleventh Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"op":1,"ar":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"50","1":"26, 27","2":"12","3":"6"}},{"t":"case","label":"Davis v. Fort Bend Cty.","cite":"2013 WL 5157191","y":2013,"court":"S.D. Tex. Sept. 11","op":1,"by":{"0":"10"}},{"t":"case","label":"Davis v. Fort Bend Cty.","cite":"765 F.3d 480","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/765/480/","op":1,"by":{"0":"10","1":"7, 34"}},{"t":"case","label":"EEOC v. Shell Oil Co.","cite":"466 U.S. 54","y":1984,"id":"1983/82-825","sc":1,"sum":"All of the strictures embodied in Title VII and the implementing regulation pertaining to the form and content of a charge of systemic discrimination and to the timing and adequacy of the notice afforded the employer were adhered to in this case, and therefore the EEOC was entitled to enforcement of its subpoena. Pp. 61-82. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 25, 45","1":"26","2":"2, 4, 29","3":"19"}},{"t":"case","label":"EEOC v. Waffle House, Inc.","cite":"534 U.S. 279","y":2002,"id":"2001/99-1823","sc":1,"sum":"The Court held that the arbitration agreement did not bar the EEOC from pursuing victim-specific judicial relief in an ADA enforcement action. The Court reasoned that the EECO's statutory enforcement powers unambiguously authorized the EEOC to obtain the relief that it sought in its complaint, if it could prove its case against the employer.","sumSrc":"Oyez","by":{"0":"passim","3":"3, 17, 19"}},{"t":"case","label":"Elgin v. Dep’t of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"op":1,"ar":8,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"0":"passim","1":"2, 36, 39, 40","2":"27","3":"passim"}},{"t":"case","label":"Fed. Power Comm’n v. Colorado Interstate Gas Co.","cite":"348 U.S. 492","y":1955,"id":"scdb/1954-047","sc":1,"by":{"0":"21","1":"45"}},{"t":"case","label":"Franks v. Bowman Transp. Co.","cite":"424 U.S. 747","y":1976,"id":"1975/74-728","sc":1,"sum":"In a class action against respondent employer and certain labor unions (of which respondent union is the successor) petitioners alleged various racially discriminatory employment practices in violation of Title VII of the Civil Rights Act of 1964 (Act), especially with respect to employment of over-the-road (OTR) truck drivers. After certifying the action as a class action and, inter alia, designating one of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34, 48, 49","1":"22","2":"19, 20"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"ar":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"18, 19, 20, 27","1":"passim","3":"passim"}},{"t":"case","label":"Gen. Tel. Co. of the Nw., Inc. v. EEOC","cite":"446 U.S. 318","y":1980,"id":"1979/79-488","sc":1,"sum":"The EEOC may seek classwide relief under § 706 (f) (1) without being certified as the class representative under Rule 23.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 29, 45, 46","2":"4, 5, 28, 31","3":"19"}},{"t":"case","label":"Green v. Brennan","cite":"136 S. Ct. 1769","y":2016,"id":"2015/14-613","sc":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Hallstrom v. Tillamook Cty.","cite":"493 U.S. 20","y":1989,"id":"1989/88-42","sc":1,"sum":"Where a party suing under RCRA's citizen suit provision fails to meet the notice and 60-day delay requirements of § 6972(b), the action must be dismissed as barred by the terms of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53","1":"45","2":"14"}},{"t":"case","label":"Heckler v. Day","cite":"467 U.S. 104","y":1984,"id":"1983/82-1371","sc":1,"sum":"In a 5-to-4 opinion, the Court held that Congress already considered and expressly rejected the imposition of mandatory disability dispute-resolution deadlines. Such deadlines, according to congressional reports, would subordinate quality of service to timeliness.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":2,"ar":2,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"42","1":"passim","2":"13","3":"3, 5, 8, 18"}},{"t":"case","label":"Irwin v. Department of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"46, 47"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"op":1,"ar":2,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"0":"passim","1":"26, 28","2":"12","3":"5, 20, 22"}},{"t":"case","label":"Kremer v. Chem. Constr. Corp.","cite":"456 U.S. 461","y":1982,"id":"1981/80-6045","sc":1,"sum":"The District Court was required under 28 U. S. C. § 1738 to give preclusive effect to the state court decision upholding the state administrative agency's rejection of the employment discrimination claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 31, 32"}},{"t":"case","label":"Levers v. Anderson","cite":"326 U.S. 219","y":1945,"id":"scdb/1945-008","sc":1,"sum":"1. An application for a rehearing before a District Supervisor of the Alcohol Tax Unit of the Bureau of Internal Revenue, who had entered orders annulling a permit to operate a wholesale liquor business and denying applications for importer's and wholesaler's permits, is not a prerequisite to the judicial review specifically provided by § 4 (h) of the Federal Alcohol Administration Act. Pp. 220, 224.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"op":2,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"0":"37","1":"35"}},{"t":"case","label":"Macauley v. Waterman S.S. Corp.","cite":"327 U.S. 540","y":1946,"id":"scdb/1945-065","sc":1,"sum":"The Maritime Commission Price Adjustment Board notified respondent that it had been assigned to renegotiate respondent's war contracts with the Commission pursuant to the Renegotiation Act and requested respondent to attend an initial conference and to supply information. Respondent denied the Board's authority on the ground that its contracts were with a British ministry and not with the Maritime Commission. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","1":"45"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"ar":1,"sum":"Explaining that the agency’s “duty * * * to attempt conciliation of a discrimination charge prior to filing a lawsuit” is “a key component of the statutory scheme”.","sumSrc":"brief:0","by":{"0":"passim","1":"passim","2":"2, 29, 30","3":"3, 12, 20"}},{"t":"case","label":"Marquez v. Screen Actors Guild, Inc.","cite":"525 U.S. 33","y":1998,"id":"1998/97-1056","sc":1,"sum":"Announced by Justice Sandra Day O'Connor, the Court ruled collective bargaining contracts do not have to spell out what it means to be \"in good standing.\" Justice O'Conner noted that requiring membership to be specified in a contract would force all terms to be specified. There would be no limit.","sumSrc":"Oyez","by":{"0":"21, 35","1":"44","3":"15, 16"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"0":"21, 42","1":"18, 46","2":"24, 25"}},{"t":"case","label":"McDonnell Douglas Corp. v. Green","cite":"411 U.S. 792","y":1973,"id":"1972/72-490","sc":1,"op":1,"sum":"The Court held that the findings of the EEOC could not bar a suit that meets the jurisdictional requirements for suing in federal district court. The Court also held that Congress meant to prevent discriminatory hiring practices, not guarantee jobs, so that the complainant in an employment discrimination lawsuit carries the initial burden to present a prima facie case for racial discrimination.","sumSrc":"Oyez","by":{"0":"48","1":"26","2":"20","3":"19, 20"}},{"t":"case","label":"McNeil v. United States","cite":"508 U.S. 106","y":1993,"id":"1992/92-6033","sc":1,"sum":"An FTCA action may not be maintained when the claimant failed to exhaust his administrative remedies prior to filing suit, but did so before substantial progress was made in the litigation. Section 2675(a)'s unambiguous text-which commands that an \"action shall not be instituted...unless the claimant shall have first presented the claim to the appropriate... agency and his claim shall have been finally denied by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","3":"14"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Morgan","cite":"536 U.S. 101","y":2002,"id":"2001/00-1614","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964 precludes recovery for discrete acts of discrimination or retaliation that occur outside the statutory time period.","sumSrc":"Oyez","by":{"0":"26","2":"33"}},{"t":"case","label":"Nevada Dep’t of Human Res. v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"0":"46","1":"30"}},{"t":"case","label":"New York Gaslight Club, Inc. v. Carey","cite":"447 U.S. 54","y":1980,"id":"1979/79-192","sc":1,"sum":"Sections 706 (f) and 706 (k) of Title VII authorize a federal-court action to recover an award of attorney's fees for work done by the prevailing complainant in state administrative and judicial proceedings to which the complainant was referred pursuant to the provisions of Title VII, and no special circumstances exist in this case that would justify denial of a fee award. Pp. 60-71. NEW YORK GASLIGHT CLUB, INC. v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Occidental Life Ins. Co. v. EEOC","cite":"432 U.S. 355","y":1977,"id":"1976/76-99","sc":1,"sum":"About three years after an employee of petitioner company had first complained to the Equal Employment Opportunity Commission under Title VII of the Civil Rights Act of 1964 that petitioner had discriminated against her because of her sex, and five months after conciliation efforts by the EEOC had failed, the EEOC brought this enforcement action in the District Court for the Central District of California. The court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 24, 28, 29","1":"4","2":"4, 5"}},{"t":"case","label":"Patchak v. Zinke","cite":"138 S. Ct. 897","y":2018,"id":"2017/16-498","sc":1,"ar":1,"sum":"The Court held that a statute that directs the federal courts to \"promptly dismiss” certain lawsuits without affecting any underlying laws does not violate the Constitution’s separation of powers principles.","sumSrc":"Oyez","by":{"0":"42, 44","1":"42","2":"17, 24","3":"18"}},{"t":"case","label":"Reed Elsevier v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"op":3,"ar":2,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"5, 9, 10, 21"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"0":"38, 52"}},{"t":"case","label":"San Diego Bldg. Trades Council v. Garmon","cite":"359 U.S. 236","y":1959,"id":"1958/66","sc":1,"sum":"Although the National Labor Relations Board had declined to exercise jurisdiction, a California state court was precluded by the National Labor Relations Act from awarding damages to respondents under state law for economic injuries resulting from the peaceful picketing of their plant by labor unions which had not been selected by a majority of respondents' employees as their bargaining agents.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"44"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"op":6,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"14, 41","1":"14, 20, 27, 34","2":"11, 13, 33"}},{"t":"case","label":"Sims v. Apfel","cite":"530 U.S. 103","y":2000,"id":"1999/98-9537","sc":1,"sum":"The Court held, 5 to 4, that Social Security claimants who exhaust administrative remedies need not also exhaust issues administratively in order to preserve judicial review of those issues.","sumSrc":"Oyez","by":{"0":"21","1":"44","2":"28","3":"16"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"16","1":"25","2":"11, 16, 18, 21, 33","3":"9"}},{"t":"case","label":"Switchmen’s Union of N. Am. v. Nat’l Mediation Bd.","cite":"320 U.S. 297","y":1943,"id":"scdb/1943-013","sc":1,"sum":"that the District Court was without jurisdiction to review the action of the Board in issuing the certificate.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"op":1,"ar":8,"sum":"Petitioner mine operator's nonunion work force designated two employees of the United Mine Workers of America (UMWA) to serve as miners' representatives under 30 U. S. C. §813(f). Claiming that the designations compromised its rights under the National Labor Relations Act (NLRA), petitioner refused to post information about the representatives as required by a regulation issued by the Department of Labor's Mine …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"9, 27","3":"passim"}},{"t":"case","label":"Union Pac. R.R. Co. v. Bhd. of Locomotive Eng’rs","cite":"558 U.S. 67","y":2009,"id":"2009/08-604","sc":1,"op":3,"sum":"A case in which the Court further held that pre-arbitration settlement conferences are not a prerequisite for National Railroad Adjustment Board jurisdiction over a dispute.","sumSrc":"Oyez","by":{"0":"34","1":"15, 42","2":"13, 21, 24","3":"10"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"sum":"The Court ruled that Congress did not intend the \"equitable tolling\" doctrine to apply to the Internal Revenue Code of 1986's time limitations for filing tax refund claims.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 41"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"135 S. Ct. 1625","y":2015,"id":"2014/13-1074","sc":1,"op":2,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"0":"passim","2":"12, 13, 15, 19, 24","3":"5, 17"}},{"t":"case","label":"Webb v. Bd. of Educ. of Dyer Cty.","cite":"471 U.S. 234","y":1985,"id":"1984/83-1360","sc":1,"sum":"After respondent Board of Education of Dyer County, Tennessee, terminated petitioner's employment as a schoolteacher in 1974, he retained counsel to represent him in administrative proceedings before the Board. Petitioner contended, inter alia, that his discharge was racially motivated and that his constitutional rights had been violated. In 1978, the Board ultimately decided to adhere to its decision. In 1979, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22, 36, 38"}},{"t":"case","label":"Whitney Nat’l Bank in Jefferson Parish v. Bank of New Orleans & Trust Co.","cite":"379 U.S. 411","y":1965,"id":"1964/26","sc":1,"sum":"A New Orleans-based national bank, desiring to expand but prohibited from operating branches beyond its home parish, formed a holding company which in turn organized a new national bank to operate in an adjoining parish. Pursuant to the Bank Holding Company Act of 1956, the Federal Reserve Board (FRB), after receiving favorable advice from the Comptroller of the Currency (Comptroller), held hearings on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 24","3":"8, 12"}},{"t":"case","label":"Woelke & Romero Framing, Inc. v. NLRB","cite":"456 U.S. 645","y":1982,"id":"1981/80-1798","sc":1,"sum":"Section 8(e) of the National Labor Relations Act (Act) proscribes secondary agreements between unions and employers-that is, agreements that require an employer to cease doing business with another party. However, § 8(e) contains a proviso which exempts from the proscription of § 8(e) agreements between a union and an employer in the construction industry concerning the contracting or subcontracting of work to be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"44"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"ar":2,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"0":"22, 52","1":"43","2":"9, 21, 24, 26, 27","3":"9"}},{"t":"case","label":"Page(s) Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"op":2,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"9, 18, 18, 20, 21","3":"18"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"15, 16"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","subs":["(b)"],"by":{"0":"53"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":21,"ar":4,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"passim","1":"passim","2":"1","3":"passim"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"3","1":"3","2":"2"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(a)","(b)","(c)","(e)","(e)(1)","(f)","(f)(1)","(f)(2)","(f)(3)","(g)","(g)(1)","(e)(1970)"],"stext":{"head":"§2000e–5. Enforcement provisions","paras":[[0,"(a) Power of Commission to prevent unlawful employment practices"],[0,"The Commission is empowered, as hereinafter provided, to prevent any person from engaging in any unlawful employment practice as set forth in section 2000e–2 or 2000e–3 of this title."],[0,"(b) Charges by persons aggrieved or member of Commission of unlawful employment practices by employers, etc.; filing; allegations; notice to respondent; contents of notice; investigation by Commission; contents of charges; prohibition on disclosure of charges; determination of reasonable cause; conference, conciliation, and persuasion for elimination of unlawful practices; prohibition on disclosure of informal endeavors to end unlawful practices; use of evidence in subsequent proceedings; penalties for disclosure of information; time for determination of reasonable cause"],[0,"Whenever a charge is filed by or on behalf of a person claiming to be aggrieved, or by a member of the Commission, alleging that an employer, employment agency, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, has engaged in an unlawful employment practice, the Commission shall serve a notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) on such employer, employment agency, labor organization, or joint labor-management committee (hereinafter referred to as the \"respondent\") within ten days, and shall make an investigation thereof. Charges shall be in writing under oath or affirmation and shall contain such information and be in such form as the Commission requires. Charges shall not be made public by the Commission. If the Commission determines after such investigation that there is not reasonable cause to believe that the charge is true, it shall dismiss the charge and promptly notify the person claiming to be aggrieved and the respondent of its action. In determining whether reasonable cause exists, the Commission shall accord substantial weight to final findings and orders made by State or local authorities in proceedings commenced under State or local law pursuant to the requirements of subsections (c) and (d). If the Commission determines after such investigation that there is reasonable cause to believe that the charge is true, the Commission shall endeavor to eliminate any such alleged unlawful employment practice by informal methods of conference, conciliation, and persuasion. Nothing said or done during and as a part of such informal endeavors may be made public by the Commission, its officers or employees, or used as evidence in a subsequent proceeding without the written consent of the persons concerned. Any person who makes public information in violation of this subsection shall be fined not more than $1,000 or imprisoned for not more than one year, or both. The Commission shall make its determination on reasonable cause as promptly as possible and, so far as practicable, not later than one hundred and twenty days from the filing of the charge or, where applicable under subsection (c) or (d), from the date upon which the Commission is authorized to take action with respect to the charge."],[0,"(c) State or local enforcement proceedings; notification of State or local authority; time for filing charges with Commission; commencement of proceedings"],[0,"In the case of an alleged unlawful employment practice occurring in a State, or political subdivision of a State, which has a State or local law prohibiting the unlawful employment practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, no charge may be filed under subsection (a) 1 by the person aggrieved before the expiration of sixty days after proceedings have been commenced under the State or local law, unless such proceedings have been earlier terminated, provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective date of such State or local law. If any requirement for the commencement of such proceedings is imposed by a State or local authority other than a requirement of the filing of a written and signed statement of the facts upon which the proceeding is based, the proceeding shall be deemed to have been commenced for the purposes of this subsection at the time such statement is sent by registered mail to the appropriate State or local authority."],[0,"(d) State or local enforcement proceedings; notification of State or local authority; time for action on charges by Commission"],[0,"In the case of any charge filed by a member of the Commission alleging an unlawful employment practice occurring in a State or political subdivision of a State which has a State or local law prohibiting the practice alleged and establishing or authorizing a State or local authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, the Commission shall, before taking any action with respect to such charge, notify the appropriate State or local officials and, upon request, afford them a reasonable time, but not less than sixty days (provided that such sixty-day period shall be extended to one hundred and twenty days during the first year after the effective day of such State or local law), unless a shorter period is requested, to act under such State or local law to remedy the practice alleged."],[0,"(e) Time for filing charges; time for service of notice of charge on respondent; filing of charge by Commission with State or local agency; seniority system"],[0,"(1) A charge under this section shall be filed within one hundred and eighty days after the alleged unlawful employment practice occurred and notice of the charge (including the date, place and circumstances of the alleged unlawful employment practice) shall be served upon the person against whom such charge is made within ten days thereafter, except that in a case of an unlawful employment practice with respect to which the person aggrieved has initially instituted proceedings with a State or local agency with authority to grant or seek relief from such practice or to institute criminal proceedings with respect thereto upon receiving notice thereof, such charge shall be filed by or on behalf of the person aggrieved within three hundred days after the alleged unlawful employment practice occurred, or within thirty days after receiving notice that the State or local agency has terminated the proceedings under the State or local law, whichever is earlier, and a copy of such charge shall be filed by the Commission with the State or local agency."],[0,"(2) For purposes of this section, an unlawful employment practice occurs, with respect to a seniority system that has been adopted for an intentionally discriminatory purpose in violation of this subchapter (whether or not that discriminatory purpose is apparent on the face of the seniority provision), when the seniority system is adopted, when an individual becomes subject to the seniority system, or when a person aggrieved is injured by the application of the seniority system or provision of the system."],[0,"(3)(A) For purposes of this section, an unlawful employment practice occurs, with respect to discrimination in compensation in violation of this subchapter, when a discriminatory compensation decision or other practice is adopted, when an individual becomes subject to a discriminatory compensation decision or other practice, or when an individual is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(B) In addition to any relief authorized by section 1981a of this title, liability may accrue and an aggrieved person may obtain relief as provided in subsection (g)(1), including recovery of back pay for up to two years preceding the filing of the charge, where the unlawful employment practices that have occurred during the charge filing period are similar or related to unlawful employment practices with regard to discrimination in compensation that occurred outside the time for filing a charge."],[0,"(f) Civil action by Commission, Attorney General, or person aggrieved; preconditions; procedure; appointment of attorney; payment of fees, costs, or security; intervention; stay of Federal proceedings; action for appropriate temporary or preliminary relief pending final disposition of charge; jurisdiction and venue of United States courts; designation of judge to hear and determine case; assignment of case for hearing; expedition of case; appointment of master"],[0,"(1) If within thirty days after a charge is filed with the Commission or within thirty days after expiration of any period of reference under subsection (c) or (d), the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission may bring a civil action against any respondent not a government, governmental agency, or political subdivision named in the charge. In the case of a respondent which is a government, governmental agency, or political subdivision, if the Commission has been unable to secure from the respondent a conciliation agreement acceptable to the Commission, the Commission shall take no further action and shall refer the case to the Attorney General who may bring a civil action against such respondent in the appropriate United States district court. The person or persons aggrieved shall have the right to intervene in a civil action brought by the Commission or the Attorney General in a case involving a government, governmental agency, or political subdivision. If a charge filed with the Commission pursuant to subsection (b), is dismissed by the Commission, or if within one hundred and eighty days from the filing of such charge or the expiration of any period of reference under subsection (c) or (d), whichever is later, the Commission has not filed a civil action under this section or the Attorney General has not filed a civil action in a case involving a government, governmental agency, or political subdivision, or the Commission has not entered into a conciliation agreement to which the person aggrieved is a party, the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, shall so notify the person aggrieved and within ninety days after the giving of such notice a civil action may be brought against the respondent named in the charge (A) by the person claiming to be aggrieved or (B) if such charge was filed by a member of the Commission, by any person whom the charge alleges was aggrieved by the alleged unlawful employment practice. Upon application by the complainant and in such circumstances as the court may deem just, the court may appoint an attorney for such complainant and may authorize the commencement of the action without the payment of fees, costs, or security. Upon timely application, the court may, in its discretion, permit the Commission, or the Attorney General in a case involving a government, governmental agency, or political subdivision, to intervene in such civil action upon certification that the case is of general public importance. Upon request, the court may, in its discretion, stay further proceedings for not more than sixty days pending the termination of State or local proceedings described in subsection (c) or (d) of this section or further efforts of the Commission to obtain voluntary compliance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-5?type=usc&year=mostrecent&link-type=html"},"ar":4,"head":"§2000e–5. Enforcement provisions","tname":"The Public Health and Welfare","by":{"0":"43, 46, 3, passim, 5, 24, 31, 34, 33, 43, 44, 46, 47, passim, 43, 44, 7, 17, 43, 43, 48, 43","1":"31, 4, 3, 23, 3, passim, 19, 40","2":"4, 29, 4, 29, 4, 29, 4, 29, 4, 29, 4, 29, 4, 29","3":"17, 21, 12, 12, 19, 20, 24, 18, 18, 21, 18, 20, 21, 24, 18"}},{"t":"usc","label":"42 U.S.C. § 2000e-6","url":"https://www.law.cornell.edu/uscode/text/42/2000e-6","by":{"0":"26"}},{"t":"usc","label":"42 U.S.C. § 2000e-8","url":"https://www.law.cornell.edu/uscode/text/42/2000e-8","subs":["(a)"],"stext":{"head":"§2000e–8. Investigations","paras":[[0,"(a) Examination and copying of evidence related to unlawful employment practices"],[0,"In connection with any investigation of a charge filed under section 2000e–5 of this title, the Commission or its designated representative shall at all reasonable times have access to, for the purposes of examination, and the right to copy any evidence of any person being investigated or proceeded against that relates to unlawful employment practices covered by this subchapter and is relevant to the charge under investigation."],[0,"(b) Cooperation with State and local agencies administering State fair employment practices laws; participation in and contribution to research and other projects; utilization of services; payment in advance or reimbursement; agreements and rescission of agreements"],[0,"The Commission may cooperate with State and local agencies charged with the administration of State fair employment practices laws and, with the consent of such agencies, may, for the purpose of carrying out its functions and duties under this subchapter and within the limitation of funds appropriated specifically for such purpose, engage in and contribute to the cost of research and other projects of mutual interest undertaken by such agencies, and utilize the services of such agencies and their employees, and, notwithstanding any other provision of law, pay by advance or reimbursement such agencies and their employees for services rendered to assist the Commission in carrying out this subchapter. In furtherance of such cooperative efforts, the Commission may enter into written agreements with such State or local agencies and such agreements may include provisions under which the Commission shall refrain from processing a charge in any cases or class of cases specified in such agreements or under which the Commission shall relieve any person or class of persons in such State or locality from requirements imposed under this section. The Commission shall rescind any such agreement whenever it determines that the agreement no longer serves the interest of effective enforcement of this subchapter."],[0,"(c) Execution, retention, and preservation of records; reports to Commission; training program records; appropriate relief from regulation or order for undue hardship; procedure for exemption; judicial action to compel compliance"],[0,"Every employer, employment agency, and labor organization subject to this subchapter shall (1) make and keep such records relevant to the determinations of whether unlawful employment practices have been or are being committed, (2) preserve such records for such periods, and (3) make such reports therefrom as the Commission shall prescribe by regulation or order, after public hearing, as reasonable, necessary, or appropriate for the enforcement of this subchapter or the regulations or orders thereunder. The Commission shall, by regulation, require each employer, labor organization, and joint labor-management committee subject to this subchapter which controls an apprenticeship or other training program to maintain such records as are reasonably necessary to carry out the purposes of this subchapter, including, but not limited to, a list of applicants who wish to participate in such program, including the chronological order in which applications were received, and to furnish to the Commission upon request, a detailed description of the manner in which persons are selected to participate in the apprenticeship or other training program. Any employer, employment agency, labor organization, or joint labor-management committee which believes that the application to it of any regulation or order issued under this section would result in undue hardship may apply to the Commission for an exemption from the application of such regulation or order, and, if such application for an exemption is denied, bring a civil action in the United States district court for the district where such records are kept. If the Commission or the court, as the case may be, finds that the application of the regulation or order to the employer, employment agency, or labor organization in question would impose an undue hardship, the Commission or the court, as the case may be, may grant appropriate relief. If any person required to comply with the provisions of this subsection fails or refuses to do so, the United States district court for the district in which such person is found, resides, or transacts business, shall, upon application of the Commission, or the Attorney General in a case involving a government, governmental agency or political subdivision, have jurisdiction to issue to such person an order requiring him to comply."],[0,"(d) Consultation and coordination between Commission and interested State and Federal agencies in prescribing recordkeeping and reporting requirements; availability of information furnished pursuant to recordkeeping and reporting requirements; conditions on availability"],[0,"In prescribing requirements pursuant to subsection (c) of this section, the Commission shall consult with other interested State and Federal agencies and shall endeavor to coordinate its requirements with those adopted by such agencies. The Commission shall furnish upon request and without cost to any State or local agency charged with the administration of a fair employment practice law information obtained pursuant to subsection (c) of this section from any employer, employment agency, labor organization, or joint labor-management committee subject to the jurisdiction of such agency. Such information shall be furnished on condition that it not be made public by the recipient agency prior to the institution of a proceeding under State or local law involving such information. If this condition is violated by a recipient agency, the Commission may decline to honor subsequent requests pursuant to this subsection."],[0,"(e) Prohibited disclosures; penalties"],[0,"It shall be unlawful for any officer or employee of the Commission to make public in any manner whatever any information obtained by the Commission pursuant to its authority under this section prior to the institution of any proceeding under this subchapter involving such information. Any officer or employee of the Commission who shall make public in any manner whatever any information in violation of this subsection shall be guilty, of a misdemeanor and upon conviction thereof, shall be fined not more than $1,000, or imprisoned not more than one year."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-8?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–8. Investigations","tname":"The Public Health and Welfare","by":{"0":"25, 6","2":"4, 29"}},{"t":"usc","label":"42 U.S.C. § 2000e-9","url":"https://www.law.cornell.edu/uscode/text/42/2000e-9","by":{"0":"25, 36"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(d)","(c)","(a)","(b)"],"stext":{"head":"§2000e–16. Employment by Federal Government","paras":[[0,"(a) Discriminatory practices prohibited; employees or applicants for employment subject to coverage"],[0,"All personnel actions affecting employees or applicants for employment (except with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units of the Government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on race, color, religion, sex, or national origin."],[0,"(b) Equal Employment Opportunity Commission; enforcement powers; issuance of rules, regulations, etc.; annual review and approval of national and regional equal employment opportunity plans; review and evaluation of equal employment opportunity programs and publication of progress reports; consultations with interested parties; compliance with rules, regulations, etc.; contents of national and regional equal employment opportunity plans; authority of Librarian of Congress"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission shall have authority to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without back pay, as will effectuate the policies of this section, and shall issue such rules, regulations, orders and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the annual review and approval of a national and regional equal employment opportunity plan which each department and agency and each appropriate unit referred to in subsection (a) of this section shall submit in order to maintain an affirmative program of equal employment opportunity for all such employees and applicants for employment;"],[1,"(2) be responsible for the review and evaluation of the operation of all agency equal employment opportunity programs, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each such department, agency, or unit; and"],[1,"(3) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to equal employment opportunity."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. The plan submitted by each department, agency, and unit shall include, but not be limited to—"],[1,"(1) provision for the establishment of training and education programs designed to provide a maximum opportunity for employees to advance so as to perform at their highest potential; and"],[1,"(2) a description of the qualifications in terms of training and experience relating to equal employment opportunity for the principal and operating officials of each such department, agency, or unit responsible for carrying out the equal employment opportunity program and of the allocation of personnel and resources proposed by such department, agency, or unit to carry out its equal employment opportunity program."],[0,"With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil action by employee or applicant for employment for redress of grievances; time for bringing of action; head of department, agency, or unit as defendant"],[0,"Within 90 days of receipt of notice of final action taken by a department, agency, or unit referred to in subsection (a), or by the Equal Employment Opportunity Commission upon an appeal from a decision or order of such department, agency, or unit on a complaint of discrimination based on race, color, religion, sex or national origin, brought pursuant to subsection (a) of this section, Executive Order 11478 or any succeeding Executive orders, or after one hundred and eighty days from the filing of the initial charge with the department, agency, or unit or with the Equal Employment Opportunity Commission on appeal from a decision or order of such department, agency, or unit until such time as final action may be taken by a department, agency, or unit, an employee or applicant for employment, if aggrieved by the final disposition of his complaint, or by the failure to take final action on his complaint, may file a civil action as provided in section 2000e–5 of this title, in which civil action the head of the department, agency, or unit, as appropriate, shall be the defendant."],[0,"(d) Section 2000e–5(f) through (k) of this title applicable to civil actions"],[0,"The provisions of section 2000e–5(f) through (k) of this title, as applicable, shall govern civil actions brought hereunder, and the same interest to compensate for delay in payment shall be available as in cases involving nonpublic parties..1"],[0,"(e) Government agency or official not relieved of responsibility to assure nondiscrimination in employment or equal employment opportunity"],[0,"Nothing contained in this Act shall relieve any Government agency or official of its or his primary responsibility to assure nondiscrimination in employment as required by the Constitution and statutes or of its or his responsibilities under Executive Order 11478 relating to equal employment opportunity in the Federal Government."],[0,"(f) Section 2000e–5(e)(3) of this title applicable to compensation discrimination"],[0,"Section 2000e–5(e)(3) of this title shall apply to complaints of discrimination in compensation under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-16?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–16. Employment by Federal Government","tname":"The Public Health and Welfare","by":{"0":"26, 46, 46","1":"30, 30, 31, 30","2":"5, 5, 5, 5","3":"21, 21"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","by":{"0":"51"}},{"t":"usc","label":"5 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/5/7701","by":{"0":"51"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(b)(1)"],"stext":{"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","paras":[[0,"(a)(1) Any employee or applicant for employment adversely affected or aggrieved by a final order or decision of the Merit Systems Protection Board may obtain judicial review of the order or decision."],[0,"(2) The Board shall be named respondent in any proceeding brought pursuant to this subsection, unless the employee or applicant for employment seeks review of a final order or decision on the merits on the underlying personnel action or on a request for attorney fees, in which case the agency responsible for taking the personnel action shall be the respondent."],[0,"(b)(1)(A) Except as provided in subparagraph (B) and paragraph (2) of this subsection, a petition to review a final order or final decision of the Board shall be filed in the United States Court of Appeals for the Federal Circuit. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(B) A petition to review a final order or final decision of the Board that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D) shall be filed in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction. Notwithstanding any other provision of law, any petition for review shall be filed within 60 days after the Board issues notice of the final order or decision of the Board."],[0,"(2) Cases of discrimination subject to the provisions of section 7702 of this title shall be filed under section 717(c) of the Civil Rights Act of 1964 (42 U.S.C. 2000e–16(c)), section 15(c) of the Age Discrimination in Employment Act of 1967 (29 U.S.C. 633a(c)), and section 16(b) of the Fair Labor Standards Act of 1938, as amended (29 U.S.C. 216(b)), as applicable. Notwithstanding any other provision of law, any such case filed under any such section must be filed within 30 days after the date the individual filing the case received notice of the judicially reviewable action under such section 7702."],[0,"(c) In any case filed in the United States Court of Appeals for the Federal Circuit, the court shall review the record and hold unlawful and set aside any agency action, findings, or conclusions found to be—"],[1,"(1) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(2) obtained without procedures required by law, rule, or regulation having been followed; or"],[1,"(3) unsupported by substantial evidence;"],[0,"except that in the case of discrimination brought under any section referred to in subsection (b)(2) of this section, the employee or applicant shall have the right to have the facts subject to trial de novo by the reviewing court."],[0,"(d)(1) Except as provided under paragraph (2), this paragraph shall apply to any review obtained by the Director of the Office of Personnel Management. The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the Court of Appeals. The granting of the petition for judicial review shall be at the discretion of the Court of Appeals."],[0,"(2) This paragraph shall apply to any review obtained by the Director of the Office of Personnel Management that raises no challenge to the Board's disposition of allegations of a prohibited personnel practice described in section 2302(b) other than practices described in section 2302(b)(8), or 2302(b)(9)(A)(i), (B), (C), or (D). The Director may obtain review of any final order or decision of the Board by filing, within 60 days after the Board issues notice of the final order or decision of the Board, a petition for judicial review in the United States Court of Appeals for the Federal Circuit or any court of appeals of competent jurisdiction if the Director determines, in the discretion of the Director, that the Board erred in interpreting a civil service law, rule, or regulation affecting personnel management and that the Board's decision will have a substantial impact on a civil service law, rule, regulation, or policy directive. If the Director did not intervene in a matter before the Board, the Director may not petition for review of a Board decision under this section unless the Director first petitions the Board for a reconsideration of its decision, and such petition is denied. In addition to the named respondent, the Board and all other parties to the proceedings before the Board shall have the right to appear in the proceeding before the court of appeals. The granting of the petition for judicial review shall be at the discretion of the court of appeals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7703?type=usc&year=mostrecent&link-type=html"},"head":"§7703. Judicial review of decisions of the Merit Systems Protection Board","tname":"Government Organization and Employees","by":{"0":"51","1":"39"}},{"t":"law","label":"Pub. L. No. 92-261","url":"https://www.govinfo.gov/link/statute/86/103","by":{"0":"4","1":"20"}},{"t":"usc","label":"28 U.S.C. § 2675","url":"https://www.law.cornell.edu/uscode/text/28/2675","subs":["(a)"],"stext":{"head":"§2675. Disposition by federal agency as prerequisite; evidence","paras":[[0,"(a) An action shall not be instituted upon a claim against the United States for money damages for injury or loss of property or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, unless the claimant shall have first presented the claim to the appropriate Federal agency and his claim shall have been finally denied by the agency in writing and sent by certified or registered mail. The failure of an agency to make final disposition of a claim within six months after it is filed shall, at the option of the claimant any time thereafter, be deemed a final denial of the claim for purposes of this section. The provisions of this subsection shall not apply to such claims as may be asserted under the Federal Rules of Civil Procedure by third party complaint, cross-claim, or counterclaim."],[0,"(b) Action under this section shall not be instituted for any sum in excess of the amount of the claim presented to the federal agency, except where the increased amount is based upon newly discovered evidence not reasonably discoverable at the time of presenting the claim to the federal agency, or upon allegation and proof of intervening facts, relating to the amount of the claim."],[0,"(c) Disposition of any claim by the Attorney General or other head of a federal agency shall not be competent evidence of liability or amount of damages."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2675?type=usc&year=mostrecent&link-type=html"},"head":"§2675. Disposition by federal agency as prerequisite; evidence","tname":"Judiciary and Judicial Procedure","by":{"0":"22","1":"45"}},{"t":"usc","label":"29 U.S.C. § 161","url":"https://www.law.cornell.edu/uscode/text/29/161","by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(c)(2)","(a)"],"stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"0":"52, 53","1":"42","2":"21, 24, 26"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)","(h)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"21","1":"18, 45, 18, 45","2":"25, 25"}},{"t":"reg","label":"29 C.F.R. § 1601.12","url":"https://www.ecfr.gov/current/title-29/section-1601.12","subs":["(b)"],"by":{"0":"5","1":"3, 33"}},{"t":"reg","label":"29 C.F.R. § 1626.10","url":"https://www.ecfr.gov/current/title-29/section-1626.10","by":{"0":"8"}},{"t":"case","label":"Adamov v. U.S. Bank Nat’l Ass’n","cite":"726 F.3d 851","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/726/851/","by":{"1":"12"}},{"t":"case","label":"Anjelino v. N.Y. Times Co.","cite":"200 F.3d 73","y":1999,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/200/73/","by":{"1":"12"}},{"t":"case","label":"Artis v. Bernanke","cite":"630 F.3d 1031","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/630/1031/","by":{"1":"12, 32"}},{"t":"case","label":"Ass’n of Data Processing Serv. Orgs. v. Camp","cite":"397 U.S. 150","y":1970,"id":"1969/85","sc":1,"sum":"Petitioners, which provide data processing services to businesses generally, challenge a ruling by the Comptroller of the Currency permitting national banks, such as respondent bank, as an incident to their banking services, to make data processing services available to other banks and bank customers. The District Court dismissed the complaint, holding that petitioners lacked standing to bring the suit, and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Beard v. GSA","cite":"801 F.2d 1318","y":1986,"url":"https://www.courtlistener.com/c/F.2d/801/1318/","by":{"1":"41"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Bonilla-Ramirez v. MVM, Inc.","cite":"904 F.3d 88","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/904/88/","by":{"1":"29"}},{"t":"case","label":"Boos v. Runyon","cite":"201 F.3d 178","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/201/178/","by":{"1":"12, 34"}},{"t":"case","label":"Brown v. Snow","cite":"440 F.3d 1259","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/440/1259/","by":{"1":"33"}},{"t":"case","label":"Cervantes v. Ardagh Grp.","cite":"914 F.3d 560","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/914/560/","by":{"1":"29"}},{"t":"case","label":"Chandler v. Roudebush","cite":"425 U.S. 840","y":1976,"id":"1975/74-1599","sc":1,"sum":"The plain meaning of the statute, reinforced by the legislative history of the 1972 amendments, compels the conclusion that federal employees have the same right to a trial de novo as is enjoyed by private-sector or state-government employees under the amended Civil Rights Act of 1964. Pp. 843-864. 515 F. 2d 251, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4","2":"26"}},{"t":"case","label":"Crawford v. Babbitt","cite":"186 F.3d 1322","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/186/1322/","by":{"1":"33"}},{"t":"case","label":"Davis v. N.C. Dep’t of Corr.","cite":"48 F.3d 134","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/48/134/","by":{"1":"32"}},{"t":"case","label":"Dawson Farms, LLC v. Farm Serv. Agency","cite":"504 F.3d 592","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/504/592/","by":{"1":"43"}},{"t":"case","label":"De Medina v. Reinhardt","cite":"686 F.2d 997","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/686/997/","by":{"1":"33"}},{"t":"case","label":"Edwards v. Dep’t of the Army","cite":"708 F.2d 1344","y":1983,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/708/1344/","by":{"1":"32"}},{"t":"case","label":"EEOC v. Associated Dry Goods Corp.","cite":"449 U.S. 590","y":1981,"id":"1980/79-1068","sc":1,"sum":"Congress did not include charging parties within the \"public\" to whom disclosure of confidential information is illegal under §§ 706 (b) and 709 (e).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4"}},{"t":"case","label":"EEOC v. Farmer Bros. Co.","cite":"31 F.3d 891","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/31/891/","by":{"1":"32"}},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"op":3,"ar":6,"sum":"The Court held that the EPA has an absolute mandate to require states to meet federal standards set forth in the Clean Air Act.","sumSrc":"Oyez","by":{"1":"passim","2":"13, 21, 24","3":"10"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Fed. Express Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"sum":"The Court, in a 7-2 opinion, upheld the Second Circuit, stating that the procedure used to file the document was consistent with the design and purpose of the ADEA.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"Fowlkes v. Ironworkers Local 40","cite":"790 F.3d 378","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/790/378/","by":{"1":"32"}},{"t":"case","label":"Francis v. City of N.Y.","cite":"235 F.3d 763","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/235/763/","by":{"1":"34"}},{"t":"case","label":"Frederique-Alexandre v. Dep’t of Nat. & Envtl. Res.","cite":"478 F.3d 433","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/478/433/","by":{"1":"32"}},{"t":"case","label":"Gad v. Kan. State Univ.","cite":"787 F.3d 1032","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/787/1032/","by":{"1":"12"}},{"t":"case","label":"Gibson v. West","cite":"201 F.3d 990","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/201/990/","by":{"1":"12, 32"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"op":3,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"1":"passim","2":"12, 13","3":"22"}},{"t":"case","label":"Hassen v. Gov’t of Virgin Islands","cite":"861 F.3d 108","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/861/108/","by":{"1":"43"}},{"t":"case","label":"Hentosh v. Old Dominion Univ.","cite":"767 F.3d 413","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/767/413/","by":{"1":"32"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"op":2,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Hill v. Nicholson","cite":"383 Fed. Appx. 503","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./383/503/","sum":"Holding that exhaustion is nonjurisdictional in order to bypass the issue and affirm a dismissal on the merits.","sumSrc":"brief:1","by":{"1":"32, 34"}},{"t":"case","label":"Hoogerheide v. IRS","cite":"637 F.3d 634","y":2011,"url":"https://www.courtlistener.com/c/F.3d/637/634/","by":{"1":"43"}},{"t":"case","label":"Jackson v. Seaboard Coast Line R.R.","cite":"678 F.2d 992","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/678/992/","by":{"1":"33, 34"}},{"t":"case","label":"Jenkins v. Educ. Credit Mgmt. Corp.","cite":"212 Fed. Appx. 729","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./212/729/","by":{"1":"33"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"1":"42","2":"21, 24","3":"9"}},{"t":"case","label":"Jones v. Calvert Grp.","cite":"551 F.3d 297","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/551/297/","op":1,"by":{"1":"32"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"op":7,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"1":"10, 15","2":"14"}},{"t":"case","label":"Lincoln v. BNSF Ry. Co.","cite":"900 F.3d 1166","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/900/1166/","by":{"1":"12, 32"}},{"t":"case","label":"Littlejohn v. City of N.Y.","cite":"795 F.3d 297","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/795/297/","by":{"1":"29"}},{"t":"case","label":"Manning v. Carlin","cite":"786 F.2d 1108","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/786/1108/","by":{"1":"32"}},{"t":"case","label":"McKinnon v. Kwong Wah Rest.","cite":"83 F.3d 498","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/83/498/","by":{"1":"12, 33"}},{"t":"case","label":"McNeil v. United States","cite":"508 U.S 106","y":1993,"url":"https://www.courtlistener.com/c/U.S/508/106/","by":{"1":"45"}},{"t":"case","label":"Mohr v. Dustrol, Inc.","cite":"306 F.3d 636","y":2002,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/306/636/","by":{"1":"32, 33"}},{"t":"case","label":"Munsell v. Dep’t of Agric.","cite":"509 F.3d 572","y":2007,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/509/572/","by":{"1":"43"}},{"t":"case","label":"Musacchio v. United States","cite":"136 S. Ct. 709","y":2016,"id":"2015/14-1095","sc":1,"op":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Oscar Mayer & Co. v. Evans","cite":"441 U.S. 750","y":1979,"id":"1978/78-275","sc":1,"sum":"Section 14 (b) of the Age Discrimination in Employment Act of 1967 (ADEA) provides that in the case of an alleged unlawful practice occurring in a State which has a law prohibiting discrimination in employment because of age and authorizing a state authority to grant and seek relief from such discriminatory practice, no suit may be brought under § 7 (c) of the ADEA before the expiration of 60 days after proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25","3":"9, 20"}},{"t":"case","label":"Peppers v. Cobb Cty.","cite":"835 F.3d 1289","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/835/1289/","by":{"1":"32"}},{"t":"case","label":"Rester v. Stephens Media, LLC","cite":"739 F.3d 1127","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/1127/","by":{"1":"32"}},{"t":"case","label":"Robinson v. Geithner","cite":"359 Fed. Appx. 726","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./359/726/","by":{"1":"32, 33"}},{"t":"case","label":"Rockwell Int’l Corp. v. United States","cite":"549 U.S. 457","y":2007,"id":"2006/05-1272","sc":1,"sum":"The Court ruled 6-2 that Stone did not qualify as an \"original source\" with \"direct and independent knowledge of the information on which the allegations are based\" for purposes of the False Claims Act.","sumSrc":"Oyez","by":{"1":"16","2":"16, 17"}},{"t":"case","label":"Ruffin v. Lockheed Martin Corp.","cite":"659 Fed. Appx. 744","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./659/744/","by":{"1":"32"}},{"t":"case","label":"Salas v. Indep. Elec. Contractors, Inc.","cite":"603 Fed. Appx. 607","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./603/607/","by":{"1":"32"}},{"t":"case","label":"Sinochem Int’l Co. v. Malaysia Int’l Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"sum":"The Court ruled 9-0 that \"a court need not resolve whether it has [...] personal jurisdiction over the defendant if it determines that [...] a foreign tribunal is plainly the more suitable arbiter of the merits of the case.\" The opinion by Justice Ruth Bader Ginsburg held that while the first step of a court is normally to determine whether it has jurisdiction, a court can dismiss a case for forum non conveniens without establishing subject-matter or personal jurisdiction.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Sommatino v. United States","cite":"255 F.3d 704","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/255/704/","by":{"1":"32"}},{"t":"case","label":"Stache v. Int’l Union of Bricklayers","cite":"852 F.2d 1231","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/852/1231/","by":{"1":"33"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"sum":"The Court held that the Bankruptcy Court did not have the constitutional authority to enter judgement on the petitioner's counterclaim.","sumSrc":"Oyez","by":{"1":"14, 22"}},{"t":"case","label":"Strickland v. Washington","cite":"466 U.S. 668","y":1984,"id":"1983/82-1554","sc":1,"sum":"The Supreme Court held that: (1) counsel's performance must be deficient; and (2) the deficient performance must have prejudiced the defense so as to deprive the defendant of a fair trial.","sumSrc":"Oyez","by":{"1":"43","3":"9"}},{"t":"case","label":"Thomas v. Nicholson","cite":"263 Fed. Appx. 814","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./263/814/","by":{"1":"32"}},{"t":"case","label":"Tonkin v. Shadow Mgmt., Inc.","cite":"605 Fed. Appx. 194","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./605/194/","by":{"1":"32"}},{"t":"case","label":"United States v. Wong","cite":"135 S. Ct. 1625","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1625/","sc":1,"by":{"1":"passim"}},{"t":"case","label":"Whitaker v. Nash Cty.","cite":"504 Fed. Appx. 237","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./504/237/","by":{"1":"32"}},{"t":"case","label":"Wilson v. MVM, Inc.","cite":"475 F.3d 166","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/475/166/","by":{"1":"32"}},{"t":"case","label":"Yellow Freight Sys., Inc. v. Donnelly","cite":"494 U.S. 820","y":1990,"id":"1989/89-431","sc":1,"sum":"Federal courts do not have exclusive jurisdiction over Title VII actions. The fact that Title VII contains no language that expressly confines jurisdiction to federal courts or ousts state courts of their jurisdiction is strong evidence that Congress did not intend to divest state courts of concurrent jurisdiction. Although most legislators, judges, and administrators who have been involved in the enactment and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 21"}},{"t":"case","label":"Ziya v. Glob. Linguistic Sol.","cite":"645 Fed. Appx. 573","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./645/573/","by":{"1":"32"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(g)(1)(D)"],"by":{"1":"17, 17"}},{"t":"usc","label":"7 U.S.C. § 6912","url":"https://www.law.cornell.edu/uscode/text/7/6912","subs":["(e)"],"by":{"1":"43"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(a)(3)"],"by":{"1":"38"}},{"t":"usc","label":"17 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/17/411","subs":["(a)"],"stext":{"head":"§411. Registration and civil infringement actions","paras":[[0,"(a) Except for an action brought for a violation of the rights of the author under section 106A(a), and subject to the provisions of subsection (b),1 no civil action for infringement of the copyright in any United States work shall be instituted until preregistration or registration of the copyright claim has been made in accordance with this title. In any case, however, where the deposit, application, and fee required for registration have been delivered to the Copyright Office in proper form and registration has been refused, the applicant is entitled to institute a civil action for infringement if notice thereof, with a copy of the complaint, is served on the Register of Copyrights. The Register may, at his or her option, become a party to the action with respect to the issue of registrability of the copyright claim by entering an appearance within sixty days after such service, but the Register's failure to become a party shall not deprive the court of jurisdiction to determine that issue."],[0,"(b)(1) A certificate of registration satisfies the requirements of this section and section 412, regardless of whether the certificate contains any inaccurate information, unless—"],[1,"(A) the inaccurate information was included on the application for copyright registration with knowledge that it was inaccurate; and"],[1,"(B) the inaccuracy of the information, if known, would have caused the Register of Copyrights to refuse registration."],[0,"(2) In any case in which inaccurate information described under paragraph (1) is alleged, the court shall request the Register of Copyrights to advise the court whether the inaccurate information, if known, would have caused the Register of Copyrights to refuse registration."],[0,"(3) Nothing in this subsection shall affect any rights, obligations, or requirements of a person related to information contained in a registration certificate, except for the institution of and remedies in infringement actions under this section and section 412."],[0,"(c) In the case of a work consisting of sounds, images, or both, the first fixation of which is made simultaneously with its transmission, the copyright owner may, either before or after such fixation takes place, institute an action for infringement under section 501, fully subject to the remedies provided by sections 502 through 505 and section 510, if, in accordance with requirements that the Register of Copyrights shall prescribe by regulation, the copyright owner—"],[1,"(1) serves notice upon the infringer, not less than 48 hours before such fixation, identifying the work and the specific time and source of its first transmission, and declaring an intention to secure copyright in the work; and"],[1,"(2) makes registration for the work, if required by subsection (a), within three months after its first transmission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/411?type=usc&year=mostrecent&link-type=html"},"head":"§411. Registration and civil infringement actions","tname":"Copyrights","by":{"1":"18","2":"13"}},{"t":"usc","label":"17 U.S.C. § 1009","url":"https://www.law.cornell.edu/uscode/text/17/1009","subs":["(a)","(b)"],"by":{"1":"17, 17"}},{"t":"usc","label":"17 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/17/1203","subs":["(a)"],"by":{"1":"17"}},{"t":"usc","label":"26 U.S.C. § 7433","url":"https://www.law.cornell.edu/uscode/text/26/7433","subs":["(d)"],"by":{"1":"43, 43"}},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","by":{"1":"44"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"1":"44"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(9)"],"by":{"1":"39"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"1":"passim","2":"25"}},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","by":{"1":"16"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"by":{"1":"18"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"1":"3, 25"}},{"t":"usc","label":"29 U.S.C. § 633","url":"https://www.law.cornell.edu/uscode/text/29/633","subs":["(b)"],"by":{"1":"25"}},{"t":"law","label":"Pub. L. No. 93-406","url":"https://www.govinfo.gov/link/statute/88/829","by":{"1":"17"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(3)","(a)(4)","(a)(8)"],"by":{"1":"17, 17, 17"}},{"t":"usc","label":"30 U.S.C. § 816","url":"https://www.law.cornell.edu/uscode/text/30/816","subs":["(a)(1)"],"by":{"1":"38"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(b)(1)","(e)(4)(A)","(e)(4)(A)(2006)"],"stext":{"head":"§3730. Civil actions for false claims","paras":[[0,"(a) Responsibilities of the Attorney General.—The Attorney General diligently shall investigate a violation under section 3729. If the Attorney General finds that a person has violated or is violating section 3729, the Attorney General may bring a civil action under this section against the person."],[0,"(b) Actions by Private Persons.—(1) A person may bring a civil action for a violation of section 3729 for the person and for the United States Government. The action shall be brought in the name of the Government. The action may be dismissed only if the court and the Attorney General give written consent to the dismissal and their reasons for consenting."],[0,"(2) A copy of the complaint and written disclosure of substantially all material evidence and information the person possesses shall be served on the Government pursuant to Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. The complaint shall be filed in camera, shall remain under seal for at least 60 days, and shall not be served on the defendant until the court so orders. The Government may elect to intervene and proceed with the action within 60 days after it receives both the complaint and the material evidence and information."],[0,"(3) The Government may, for good cause shown, move the court for extensions of the time during which the complaint remains under seal under paragraph (2). Any such motions may be supported by affidavits or other submissions in camera. The defendant shall not be required to respond to any complaint filed under this section until 20 days after the complaint is unsealed and served upon the defendant pursuant to Rule 4 of the Federal Rules of Civil Procedure."],[0,"(4) Before the expiration of the 60-day period or any extensions obtained under paragraph (3), the Government shall—"],[1,"(A) proceed with the action, in which case the action shall be conducted by the Government; or"],[1,"(B) notify the court that it declines to take over the action, in which case the person bringing the action shall have the right to conduct the action."],[0,"(5) When a person brings an action under this subsection, no person other than the Government may intervene or bring a related action based on the facts underlying the pending action."],[0,"(c) Rights of the Parties to Qui Tam Actions.—(1) If the Government proceeds with the action, it shall have the primary responsibility for prosecuting the action, and shall not be bound by an act of the person bringing the action. Such person shall have the right to continue as a party to the action, subject to the limitations set forth in paragraph (2)."],[0,"(2)(A) The Government may dismiss the action notwithstanding the objections of the person initiating the action if the person has been notified by the Government of the filing of the motion and the court has provided the person with an opportunity for a hearing on the motion."],[0,"(B) The Government may settle the action with the defendant notwithstanding the objections of the person initiating the action if the court determines, after a hearing, that the proposed settlement is fair, adequate, and reasonable under all the circumstances. Upon a showing of good cause, such hearing may be held in camera."],[0,"(C) Upon a showing by the Government that unrestricted participation during the course of the litigation by the person initiating the action would interfere with or unduly delay the Government's prosecution of the case, or would be repetitious, irrelevant, or for purposes of harassment, the court may, in its discretion, impose limitations on the person's participation, such as—"],[1,"(i) limiting the number of witnesses the person may call;"],[1,"(ii) limiting the length of the testimony of such witnesses;"],[1,"(iii) limiting the person's cross-examination of witnesses; or"],[1,"(iv) otherwise limiting the participation by the person in the litigation."],[0,"(D) Upon a showing by the defendant that unrestricted participation during the course of the litigation by the person initiating the action would be for purposes of harassment or would cause the defendant undue burden or unnecessary expense, the court may limit the participation by the person in the litigation."],[0,"(3) If the Government elects not to proceed with the action, the person who initiated the action shall have the right to conduct the action. If the Government so requests, it shall be served with copies of all pleadings filed in the action and shall be supplied with copies of all deposition transcripts (at the Government's expense). When a person proceeds with the action, the court, without limiting the status and rights of the person initiating the action, may nevertheless permit the Government to intervene at a later date upon a showing of good cause."],[0,"(4) Whether or not the Government proceeds with the action, upon a showing by the Government that certain actions of discovery by the person initiating the action would interfere with the Government's investigation or prosecution of a criminal or civil matter arising out of the same facts, the court may stay such discovery for a period of not more than 60 days. Such a showing shall be conducted in camera. The court may extend the 60-day period upon a further showing in camera that the Government has pursued the criminal or civil investigation or proceedings with reasonable diligence and any proposed discovery in the civil action will interfere with the ongoing criminal or civil investigation or proceedings."],[0,"(5) Notwithstanding subsection (b), the Government may elect to pursue its claim through any alternate remedy available to the Government, including any administrative proceeding to determine a civil money penalty. If any such alternate remedy is pursued in another proceeding, the person initiating the action shall have the same rights in such proceeding as such person would have had if the action had continued under this section. Any finding of fact or conclusion of law made in such other proceeding that has become final shall be conclusive on all parties to an action under this section. For purposes of the preceding sentence, a finding or conclusion is final if it has been finally determined on appeal to the appropriate court of the United States, if all time for filing such an appeal with respect to the finding or conclusion has expired, or if the finding or conclusion is not subject to judicial review."],[0,"(d) Award to Qui Tam Plaintiff.—(1) If the Government proceeds with an action brought by a person under subsection (b), such person shall, subject to the second sentence of this paragraph, receive at least 15 percent but not more than 25 percent of the proceeds of the action or settlement of the claim, depending upon the extent to which the person substantially contributed to the prosecution of the action. Where the action is one which the court finds to be based primarily on disclosures of specific information (other than information provided by the person bringing the action) relating to allegations or transactions in a criminal, civil, or administrative hearing, in a congressional, administrative, or Government 2 Accounting Office report, hearing, audit, or investigation, or from the news media, the court may award such sums as it considers appropriate, but in no case more than 10 percent of the proceeds, taking into account the significance of the information and the role of the person bringing the action in advancing the case to litigation. Any payment to a person under the first or second sentence of this paragraph shall be made from the proceeds. Any such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(2) If the Government does not proceed with an action under this section, the person bringing the action or settling the claim shall receive an amount which the court decides is reasonable for collecting the civil penalty and damages. The amount shall be not less than 25 percent and not more than 30 percent of the proceeds of the action or settlement and shall be paid out of such proceeds. Such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(3) Whether or not the Government proceeds with the action, if the court finds that the action was brought by a person who planned and initiated the violation of section 3729 upon which the action was brought, then the court may, to the extent the court considers appropriate, reduce the share of the proceeds of the action which the person would otherwise receive under paragraph (1) or (2) of this subsection, taking into account the role of that person in advancing the case to litigation and any relevant circumstances pertaining to the violation. If the person bringing the action is convicted of criminal conduct arising from his or her role in the violation of section 3729, that person shall be dismissed from the civil action and shall not receive any share of the proceeds of the action. Such dismissal shall not prejudice the right of the United States to continue the action, represented by the Department of Justice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3730?type=usc&year=mostrecent&link-type=html"},"head":"§3730. Civil actions for false claims","tname":"Money and Finance","by":{"1":"17, 16","2":"17"}},{"t":"usc","label":"35 U.S.C. § 292","url":"https://www.law.cornell.edu/uscode/text/35/292","subs":["(b)"],"by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 2000e-3","url":"https://www.law.cornell.edu/uscode/text/42/2000e-3","subs":["(a)"],"by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 7607","url":"https://www.law.cornell.edu/uscode/text/42/7607","subs":["(d)(7)(B)"],"stext":{"head":"§7607. Administrative proceedings and judicial review","paras":[[0,"(a) Administrative subpenas; confidentiality; witnesses"],[0,"In connection with any determination under section 7410(f) of this title, or for purposes of obtaining information under section 7521(b)(4) 1 or 7545(c)(3) of this title, any investigation, monitoring, reporting requirement, entry, compliance inspection, or administrative enforcement proceeding under the 2 chapter (including but not limited to section 7413, section 7414, section 7420, section 7429, section 7477, section 7524, section 7525, section 7542, section 7603, or section 7606 of this title),,3 the Administrator may issue subpenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents, and he may administer oaths. Except for emission data, upon a showing satisfactory to the Administrator by such owner or operator that such papers, books, documents, or information or particular part thereof, if made public, would divulge trade secrets or secret processes of such owner or operator, the Administrator shall consider such record, report, or information or particular portion thereof confidential in accordance with the purposes of section 1905 of title 18, except that such paper, book, document, or information may be disclosed to other officers, employees, or authorized representatives of the United States concerned with carrying out this chapter, to persons carrying out the National Academy of Sciences' study and investigation provided for in section 7521(c) of this title, or when relevant in any proceeding under this chapter. Witnesses summoned shall be paid the same fees and mileage that are paid witnesses in the courts of the United States. In case of contumacy or refusal to obey a subpena served upon any person under this subparagraph,4 the district court of the United States for any district in which such person is found or resides or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the Administrator to appear and produce papers, books, and documents before the Administrator, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."],[0,"(b) Judicial review"],[0,"(1) A petition for review of action of the Administrator in promulgating any national primary or secondary ambient air quality standard, any emission standard or requirement under section 7412 of this title, any standard of performance or requirement under section 7411 of this title,,3 any standard under section 7521 of this title (other than a standard required to be prescribed under section 7521(b)(1) of this title), any determination under section 7521(b)(5) 1 of this title, any control or prohibition under section 7545 of this title, any standard under section 7571 of this title, any rule issued under section 7413, 7419, or under section 7420 of this title, or any other nationally applicable regulations promulgated, or final action taken, by the Administrator under this chapter may be filed only in the United States Court of Appeals for the District of Columbia. A petition for review of the Administrator's action in approving or promulgating any implementation plan under section 7410 of this title or section 7411(d) of this title, any order under section 7411(j) of this title, under section 7412 of this title, under section 7419 of this title, or under section 7420 of this title, or his action under section 1857c–10(c)(2)(A), (B), or (C) of this title (as in effect before August 7, 1977) or under regulations thereunder, or revising regulations for enhanced monitoring and compliance certification programs under section 7414(a)(3) of this title, or any other final action of the Administrator under this chapter (including any denial or disapproval by the Administrator under subchapter I) which is locally or regionally applicable may be filed only in the United States Court of Appeals for the appropriate circuit. Notwithstanding the preceding sentence a petition for review of any action referred to in such sentence may be filed only in the United States Court of Appeals for the District of Columbia if such action is based on a determination of nationwide scope or effect and if in taking such action the Administrator finds and publishes that such action is based on such a determination. Any petition for review under this subsection shall be filed within sixty days from the date notice of such promulgation, approval, or action appears in the Federal Register, except that if such petition is based solely on grounds arising after such sixtieth day, then any petition for review under this subsection shall be filed within sixty days after such grounds arise. The filing of a petition for reconsideration by the Administrator of any otherwise final rule or action shall not affect the finality of such rule or action for purposes of judicial review nor extend the time within which a petition for judicial review of such rule or action under this section may be filed, and shall not postpone the effectiveness of such rule or action."],[0,"(2) Action of the Administrator with respect to which review could have been obtained under paragraph (1) shall not be subject to judicial review in civil or criminal proceedings for enforcement. Where a final decision by the Administrator defers performance of any nondiscretionary statutory action to a later time, any person may challenge the deferral pursuant to paragraph (1)."],[0,"(c) Additional evidence"],[0,"In any judicial proceeding in which review is sought of a determination under this chapter required to be made on the record after notice and opportunity for hearing, if any party applies to the court for leave to adduce additional evidence, and shows to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the proceeding before the Administrator, the court may order such additional evidence (and evidence in rebuttal thereof) to be taken before the Administrator, in such manner and upon such terms and conditions as to 5 the court may deem proper. The Administrator may modify his findings as to the facts, or make new findings, by reason of the additional evidence so taken and he shall file such modified or new findings, and his recommendation, if any, for the modification or setting aside of his original determination, with the return of such additional evidence."],[0,"(d) Rulemaking"],[0,"(1) This subsection applies to—"],[1,"(A) the promulgation or revision of any national ambient air quality standard under section 7409 of this title,"],[1,"(B) the promulgation or revision of an implementation plan by the Administrator under section 7410(c) of this title,"],[1,"(C) the promulgation or revision of any standard of performance under section 7411 of this title, or emission standard or limitation under section 7412(d) of this title, any standard under section 7412(f) of this title, or any regulation under section 7412(g)(1)(D) and (F) 6 of this title, or any regulation under section 7412(m) or (n) of this title,"],[1,"(D) the promulgation of any requirement for solid waste combustion under section 7429 of this title,"],[1,"(E) the promulgation or revision of any regulation pertaining to any fuel or fuel additive under section 7545 of this title,"],[1,"(F) the promulgation or revision of any aircraft emission standard under section 7571 of this title,"],[1,"(G) the promulgation or revision of any regulation under subchapter IV–A (relating to control of acid deposition),"],[1,"(H) promulgation or revision of regulations pertaining to primary nonferrous smelter orders under section 7419 of this title (but not including the granting or denying of any such order),"],[1,"(I) promulgation or revision of regulations under subchapter VI (relating to stratosphere and ozone protection),"],[1,"(J) promulgation or revision of regulations under part C of subchapter I (relating to prevention of significant deterioration of air quality and protection of visibility),"],[1,"(K) promulgation or revision of regulations under section 7521 of this title and test procedures for new motor vehicles or engines under section 7525 of this title, and the revision of a standard under section 7521(a)(3) of this title,"],[1,"(L) promulgation or revision of regulations for noncompliance penalties under section 7420 of this title,"],[1,"(M) promulgation or revision of any regulations promulgated under section 7541 of this title (relating to warranties and compliance by vehicles in actual use),"],[1,"(N) action of the Administrator under section 7426 of this title (relating to interstate pollution abatement),"],[1,"(O) the promulgation or revision of any regulation pertaining to consumer and commercial products under section 7511b(e) of this title,"],[1,"(P) the promulgation or revision of any regulation pertaining to field citations under section 7413(d)(3) of this title,"],[1,"(Q) the promulgation or revision of any regulation pertaining to urban buses or the clean-fuel vehicle, clean-fuel fleet, and clean fuel programs under part C of subchapter II,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7607?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7607. Administrative proceedings and judicial review","tname":"The Public Health and Welfare","by":{"1":"17, 42","3":"10"}},{"t":"usc","label":"45 U.S.C. § 152","url":"https://www.law.cornell.edu/uscode/text/45/152","stext":{"head":"§152. General duties","paras":[[0,"First. Duty of carriers and employees to settle disputes"],[0,"It shall be the duty of all carriers, their officers, agents, and employees to exert every reasonable effort to make and maintain agreements concerning rates of pay, rules, and working conditions, and to settle all disputes, whether arising out of the application of such agreements or otherwise, in order to avoid any interruption to commerce or to the operation of any carrier growing out of any dispute between the carrier and the employees thereof."],[0,"Second. Consideration of disputes by representatives"],[0,"All disputes between a carrier or carriers and its or their employees shall be considered, and, if possible, decided, with all expedition, in conference between representatives designated and authorized so to confer, respectively, by the carrier or carriers and by the employees thereof interested in the dispute."],[0,"Third. Designation of representatives"],[0,"Representatives, for the purposes of this chapter, shall be designated by the respective parties without interference, influence, or coercion by either party over the designation of representatives by the other; and neither party shall in any way interfere with, influence, or coerce the other in its choice of representatives. Representatives of employees for the purposes of this chapter need not be persons in the employ of the carrier, and no carrier shall, by interference, influence, or coercion seek in any manner to prevent the designation by its employees as their representatives of those who or which are not employees of the carrier."],[0,"Fourth. Organization and collective bargaining; freedom from interference by carrier; assistance in organizing or maintaining organization by carrier forbidden; deduction of dues from wages forbidden"],[0,"Employees shall have the right to organize and bargain collectively through representatives of their own choosing. The majority of any craft or class of employees shall have the right to determine who shall be the representative of the craft or class for the purposes of this chapter. No carrier, its officers, or agents shall deny or in any way question the right of its employees to join, organize, or assist in organizing the labor organization of their choice, and it shall be unlawful for any carrier to interfere in any way with the organization of its employees, or to use the funds of the carrier in maintaining or assisting or contributing to any labor organization, labor representative, or other agency of collective bargaining, or in performing any work therefor, or to influence or coerce employees in an effort to induce them to join or remain or not to join or remain members of any labor organization, or to deduct from the wages of employees any dues, fees, assessments, or other contributions payable to labor organizations, or to collect or to assist in the collection of any such dues, fees, assessments, or other contributions: Provided, That nothing in this chapter shall be construed to prohibit a carrier from permitting an employee, individually, or local representatives of employees from conferring with management during working hours without loss of time, or to prohibit a carrier from furnishing free transportation to its employees while engaged in the business of a labor organization."],[0,"Fifth. Agreements to join or not to join labor organizations forbidden"],[0,"No carrier, its officers, or agents shall require any person seeking employment to sign any contract or agreement promising to join or not to join a labor organization; and if any such contract has been enforced prior to the effective date of this chapter, then such carrier shall notify the employees by an appropriate order that such contract has been discarded and is no longer binding on them in any way."],[0,"Sixth. Conference of representatives; time; place; private agreements"],[0,"In case of a dispute between a carrier or carriers and its or their employees, arising out of grievances or out of the interpretation or application of agreements concerning rates of pay, rules, or working conditions, it shall be the duty of the designated representative or representatives of such carrier or carriers and of such employees, within ten days after the receipt of notice of a desire on the part of either party to confer in respect to such dispute, to specify a time and place at which such conference shall be held: Provided, (1) That the place so specified shall be situated upon the line of the carrier involved or as otherwise mutually agreed upon; and (2) that the time so specified shall allow the designated conferees reasonable opportunity to reach such place of conference, but shall not exceed twenty days from the receipt of such notice: And provided further, That nothing in this chapter shall be construed to supersede the provisions of any agreement (as to conferences) then in effect between the parties."],[0,"Seventh. Change in pay, rules, or working conditions contrary to agreement or to section 156 forbidden"],[0,"No carrier, its officers, or agents shall change the rates of pay, rules, or working conditions of its employees, as a class, as embodied in agreements except in the manner prescribed in such agreements or in section 156 of this title."],[0,"Eighth. Notices of manner of settlement of disputes; posting"],[0,"Every carrier shall notify its employees by printed notices in such form and posted at such times and places as shall be specified by the Mediation Board that all disputes between the carrier and its employees will be handled in accordance with the requirements of this chapter, and in such notices there shall be printed verbatim, in large type, the third, fourth, and fifth paragraphs of this section. The provisions of said paragraphs are made a part of the contract of employment between the carrier and each employee, and shall be held binding upon the parties, regardless of any other express or implied agreements between them."],[0,"Ninth. Disputes as to identity of representatives; designation by Mediation Board; secret elections"],[0,"If any dispute shall arise among a carrier's employees as to who are the representatives of such employees designated and authorized in accordance with the requirements of this chapter, it shall be the duty of the Mediation Board, upon request of either party to the dispute, to investigate such dispute and to certify to both parties, in writing, within thirty days after the receipt of the invocation of its services, the name or names of the individuals or organizations that have been designated and authorized to represent the employees involved in the dispute, and certify the same to the carrier. Upon receipt of such certification the carrier shall treat with the representative so certified as the representative of the craft or class for the purposes of this chapter. In such an investigation, the Mediation Board shall be authorized to take a secret ballot of the employees involved, or to utilize any other appropriate method of ascertaining the names of their duly designated and authorized representatives in such manner as shall insure the choice of representatives by the employees without interference, influence, or coercion exercised by the carrier. In the conduct of any election for the purposes herein indicated the Board shall designate who may participate in the election and establish the rules to govern the election, or may appoint a committee of three neutral persons who after hearing shall within ten days designate the employees who may participate in the election. In any such election for which there are 3 or more options (including the option of not being represented by any labor organization) on the ballot and no such option receives a majority of the valid votes cast, the Mediation Board shall arrange for a second election between the options receiving the largest and the second largest number of votes. The Board shall have access to and have power to make copies of the books and records of the carriers to obtain and utilize such information as may be deemed necessary by it to carry out the purposes and provisions of this paragraph."],[0,"Tenth. Violations; prosecution and penalties"],[0,"The willful failure or refusal of any carrier, its officers or agents, to comply with the terms of the third, fourth, fifth, seventh, or eighth paragraph of this section shall be a misdemeanor, and upon conviction thereof the carrier, officer, or agent offending shall be subject to a fine of not less than $1,000, nor more than $20,000, or imprisonment for not more than six months, or both fine and imprisonment, for each offense, and each day during which such carrier, officer, or agent shall willfully fail or refuse to comply with the terms of the said paragraphs of this section shall constitute a separate offense. It shall be the duty of any United States attorney to whom any duly designated representative of a carrier's employees may apply to institute in the proper court and to prosecute under the direction of the Attorney General of the United States, all necessary proceedings for the enforcement of the provisions of this section, and for the punishment of all violations thereof and the costs and expenses of such prosecution shall be paid out of the appropriation for the expenses of the courts of the United States: Provided, That nothing in this chapter shall be construed to require an individual employee to render labor or service without his consent, nor shall anything in this chapter be construed to make the quitting of his labor by an individual employee an illegal act; nor shall any court issue any process to compel the performance by an individual employee of such labor or service, without his consent."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/152?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§152. General duties","tname":"Railroads","by":{"1":"42"}},{"t":"reg","label":"29 C.F.R. § 1601.13","url":"https://www.ecfr.gov/current/title-29/section-1601.13","by":{"1":"3"}},{"t":"reg","label":"29 C.F.R. § 1601.28","url":"https://www.ecfr.gov/current/title-29/section-1601.28","subs":["(a)"],"by":{"1":"4"}},{"t":"reg","label":"29 C.F.R. § 1614.101","url":"https://www.ecfr.gov/current/title-29/section-1614.101","by":{"1":"30"}},{"t":"case","label":"Air Courier Conference of Am. v. American Postal Workers Union, AFL-CIO","cite":"498 U.S. 517","y":1991,"id":"1990/89-1416","sc":1,"sum":"The United States Postal Service's monopoly over the carriage of letters in and from the Nation is codified in a group of statutes known as the Private Express Statutes (PES). The monopoly was created by Congress as a revenue protection measure for the Postal Service vis-A-vis private competitors. Pursuant to a PES provision allowing it to suspend PES restrictions as to any mail route where the public interest so …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Arizona ex rel. Horne v. Geo Grp., Inc.","cite":"816 F.3d 1189","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/816/1189/","by":{"2":"31"}},{"t":"case","label":"Baldwin Cnty. Welcome Ctr. v. Brown","cite":"466 U.S. 147","y":1984,"id":"1983/83-181","sc":1,"sum":"There is no basis for giving Title VII actions a special status under the Federal Rules of Civil Procedure, as the Court of Appeals apparently did. Rule 3 states that an action \"is commenced by filing a complaint with the court,\" and Rule 8(a)(2) provides that a complaint must include \"a short and plain statement of the claim showing that the pleader is entitled to relief.\" The Court of Appeals suggested no …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Day v. McDonough","cite":"547 U.S. 198","y":2006,"id":"2005/04-1324","sc":1,"ar":1,"sum":"The Court affirmed the judgment of the Circuit Court and ruled that the District Court was within its discretion when it dismissed Day's petition.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"EEOC v. Commercial Office Prods. Co.","cite":"486 U.S. 107","y":1988,"id":"1987/86-1696","sc":1,"sum":"The judgment is reversed, and the case is remanded. 803 F. 2d 581, reversed and remanded. JUSTICE MARSHALL delivered the opinion of the Court with respect to Parts I, II-A, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"EEOC v. Sterling Jewelers Inc.","cite":"801 F.3d 96","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/801/96/","by":{"2":"4"}},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs. of Chi.","cite":"138 S. Ct. 13","y":2017,"id":"2017/16-658","sc":1,"op":3,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"2":"12, 13, 19, 24"}},{"t":"case","label":"Josephs v. Pacific Bell","cite":"443 F.3d 1050","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/443/1050/","by":{"2":"33"}},{"t":"case","label":"McKee v. McDonnell Douglas Tech. Servs. Co.","cite":"700 F.2d 260","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/700/260/","by":{"2":"33"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"sum":"Federal Rule of Civil Procedure 23(f), which establishes a 14-day deadline to seek permission to appeal an order granting or denying class certification, is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14"}},{"t":"case","label":"Thompson v. North Am. Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"op":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"United States v. Dalm","cite":"494 U.S. 596","y":1990,"id":"1989/88-1951","sc":1,"sum":"The District Court lacked jurisdiction over Dalm's refund suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"usc","label":"42 U.S.C. § 2000e-4","url":"https://www.law.cornell.edu/uscode/text/42/2000e-4","subs":["(a)"],"by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 2000e-12","url":"https://www.law.cornell.edu/uscode/text/42/2000e-12","subs":["(a)"],"by":{"2":"2"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"2":"16"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1332. Diversity of citizenship; amount in controversy; costs","tname":"Judiciary and Judicial Procedure","by":{"2":"25"}},{"t":"reg","label":"29 C.F.R. pt. 1601","url":"https://www.ecfr.gov/current/title-29/part-1601","by":{"2":"3"}},{"t":"case","label":"Hallowell v. Commons","cite":"239 U.S. 506","y":1916,"id":"scdb/1915-232","sc":1,"sum":"Under the act of June 25, 1910, the Secretary of the Interior has power to ascertain the legal heirs of an allottee Omaha Indian dying during the period in which an allotment made to him under the act of August 7,1882, was held in trust, and the decision of the Secretary is final and conclusive.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"7"}},{"t":"case","label":"Mader v. United States","cite":"654 F.3d 794","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/654/794/","by":{"3":"14"}},{"t":"case","label":"Myers v. Bethlehem Shipbuilding Corp.","cite":"303 U.S. 41","y":1938,"id":"scdb/1937-127","sc":1,"sum":"(1) That the District Court had no jurisdiction of a suit by the corpdration to enjoin the Board from holding the hearing. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"Ryan v. Gonzales","cite":"568 U.S. 57","y":2013,"id":"2012/10-930","sc":1,"op":4,"sum":"The Court held that no right to competence exists during federal habeas corpus proceedings.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Smith v. Clinton","cite":"886 F.3d 122","y":2018,"url":"https://www.courtlistener.com/c/F.3d/886/122/","sum":"Holding that, under the FTCA, district court lacked jurisdiction because plaintiffs “failed to exhaust their administrative remedies”.","sumSrc":"brief:3","by":{"3":"14"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"Texas & Pacific Railway Co. v. Abilene Cotton Oil Co.","cite":"204 U.S. 426","y":1907,"id":"scdb/1906-159","sc":1,"sum":"Where defendant in the state court contends that, consistently, with the Interstate Commerce Act, the state court hks no power to grant the relief, and such contention is essentially involved and expressly, and, in order to support the judgment, necessarily, decided adversely to the defendant, a Federal question exists and this court' can review the judgment on writ of error under § 709,'.Rev. Stat.'","sumSrc":"Headnote (U.S. Reports)","by":{"3":"7"}},{"t":"case","label":"United States v. Jones","cite":"336 U.S. 641","y":1949,"id":"scdb/1948-064","sc":1,"sum":"This amounted to a review and revision of the Commission's findings and orders and was beyond the jurisdiction of the Court of Claims. Pp. 651-653, 662-671.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"7"}},{"t":"case","label":"United States v. Ruzicka","cite":"329 U.S. 287","y":1946,"id":"scdb/1946-018","sc":1,"sum":"They can not assert this defense in an enforcement proceeding under § 8a (6) but are left to the administrative remedy specifically provided by § 8c (15). Stark v. Wickard, 321 U. S. 288, differentiated. Pp. 290-296. 152 F. 2d 167, reversed. In a suit by the Government under § 8a (6) of the Agricultural Marketing Agreement Act of 1937 against certain handlers of milk to enforce their obligation to make payments into …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8, 12"}},{"t":"case","label":"Page(s) Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(e)"],"by":{"3":"20"}}]};